19	// reads the same literal the user would.
20	const wantNotARouteRow = "Select the Local route row to trace its path"
21	
22	// routeResults returns a model with finished results over host, engine faked,
23	// the cursor on the first row.
24	func routeResults(t *testing.T, host string) (*Model, *fakeEngine) {
25		t.Helper()
26		m := typeInto(t, newTestModel(t), host)
27		fe := &fakeEngine{}
28		m.pathModel.engine = fe.engine()
29		m = feed(t, m, testutil.Key("enter"))
30		route := check(netcheck.CheckRoute, netcheck.OK, "eth0 via 192.168.1.1")
31		route.Title = "Local route"
32		m = deliver(t, m, route,
33			check(netcheck.CheckResolve, netcheck.OK, host+" resolves"),
34			check(netcheck.CheckTCP, netcheck.Fail, "Port 443 does not accept connections"),
35		)
36		if m.state != StateResults {
37			t.Fatalf("state = %v, want StateResults", m.state)
38		}
39		return m, fe
40	}
41	
42	// selectCheck moves the results cursor onto the row of id.
43	func selectCheck(t *testing.T, m *Model, id netcheck.CheckID) *Model {
44		t.Helper()
45		for range 20 {
46			if c, ok := m.checksTable.Selected(); ok && c.ID == id {
47				return m
48			}
49			m = feed(t, m, testutil.Key("down"))
50		}
51		t.Fatalf("no row for check %q in the results", id)
52		return m
53	}
54	
55	func TestHOnTheRouteRowOpensPathPrefilledWithoutTracing(t *testing.T) {
56		m, fe := routeResults(t, "example.com")
57		m = selectCheck(t, m, netcheck.CheckRoute)
58	
59		m, _ = step(t, m, testutil.Key(keymap.Diagnose))
60	
61		if m.activeTab != tabPath {
62			t.Fatalf("activeTab = %d, want tabPath (%d)", m.activeTab, tabPath)
63		}
64		if got := m.pathModel.input.Value(); got != "example.com" {
65			t.Errorf("Path field = %q, want the diagnostics host", got)
66		}
67		if m.pathModel.state != pathEditing || !m.pathModel.InEditMode() {
68			t.Errorf("Path state = %v, want editing with the field focused", m.pathModel.state)
69		}
70		if m.pathModel.running() {
71			t.Error("a trace is running; H must only prefill")
72		}
73		if fe.resolveCalls != 0 || fe.traceCalls != 0 {
74			t.Errorf("engine called (resolve %d, trace %d); nothing may be resolved or sent", fe.resolveCalls, fe.traceCalls)
75		}
76	}
77	
78	func TestHKeepsTheHostOnlyNotTheDiagnosticsPort(t *testing.T) {
79		m := typeInto(t, newTestModel(t), "example.com")
80		m.portInput.SetValue("8443")
81		m.pathModel.engine = (&fakeEngine{}).engine()
82		m = feed(t, m, testutil.Key("enter"))
83		route := check(netcheck.CheckRoute, netcheck.OK, "eth0")
84		route.Title = "Local route"
85		m = deliver(t, m, route)
86		m = selectCheck(t, m, netcheck.CheckRoute)
87	
88		m = feed(t, m, testutil.Key(keymap.Diagnose))
89	
90		if got := m.pathModel.input.Value(); got != "example.com" {
91			t.Errorf("Path field = %q, want the host alone (the Path port is not the Diagnostics port)", got)
92		}
93	}
94	
95	func TestHPrefillClearsAPreviousPathOutcome(t *testing.T) {
96		m, _ := routeResults(t, "example.com")
97		m = selectCheck(t, m, netcheck.CheckRoute)
98		m.pathModel.state = pathDone
99		m.pathModel.errText = "old failure"
100		m.pathModel.input.SetValue("old.example")
101	
102		m = feed(t, m, testutil.Key(keymap.Diagnose))
103	
104		pm := m.pathModel
105		if pm.state != pathEditing || pm.errText != "" || len(pm.hops) != 0 {
106			t.Errorf("state=%v errText=%q hops=%d, want editing with the old outcome cleared", pm.state, pm.errText, len(pm.hops))
107		}
108		if pm.input.Value() != "example.com" {
109			t.Errorf("field = %q, want example.com", pm.input.Value())
110		}
111	}
112	
113	func TestHOffTheRouteRowWarnsWithTheReasonAndStays(t *testing.T) {
114		m, fe := routeResults(t, "example.com")
115		m = selectCheck(t, m, netcheck.CheckTCP)
116	
117		m, _ = step(t, m, testutil.Key(keymap.Diagnose))
118	
119		if m.activeTab != tabDiagnostics || m.state != StateResults {
120			t.Errorf("tab=%d state=%v, want unchanged Diagnostics results", m.activeTab, m.state)
121		}
122		if m.footer.Level() != components.LevelWarning || m.footer.Text() != wantNotARouteRow {
123			t.Errorf("footer = {%v %q}, want Warn %q", m.footer.Level(), m.footer.Text(), wantNotARouteRow)
124		}
125		if m.pathModel.input.Value() != "" || fe.traceCalls != 0 || fe.resolveCalls != 0 {
126			t.Error("the Path tab was touched by a refused H")
127		}
128	}
129	
130	func TestHIsAlwaysAnnouncedOnResultsAndGreyedOffTheRouteRow(t *testing.T) {
131		m, _ := routeResults(t, "example.com")
132	
133		m = selectCheck(t, m, netcheck.CheckRoute)
134		onRoute := m.GetShortcuts()
135		if !testutil.HasShortcut(onRoute, keymap.Diagnose) || !testutil.ShortcutEnabled(onRoute, keymap.Diagnose) {
136			t.Errorf("route row: H missing or greyed: %v", testutil.ShortcutKeys(onRoute))
137		}
138	
139		m = selectCheck(t, m, netcheck.CheckTCP)
140		offRoute := m.GetShortcuts()
141		if !testutil.HasShortcut(offRoute, keymap.Diagnose) || !testutil.ShortcutDisabled(offRoute, keymap.Diagnose) {
142			t.Errorf("TCP row: H must stay announced and be greyed: %v", testutil.ShortcutKeys(offRoute))
143		}
144	
145		// Rule 130: the key set does not depend on the row.
146		if a, b := strings.Join(testutil.ShortcutKeys(onRoute), ","), strings.Join(testutil.ShortcutKeys(offRoute), ","); a != b {
147			t.Errorf("results key set changed with the row: %s -> %s", a, b)
148		}
149	}
150	
151	func TestHDoesNotCollideWithAnotherResultsShortcut(t *testing.T) {
152		m, _ := routeResults(t, "example.com")
153		seen := map[string]int{}
154		for _, k := range testutil.ShortcutKeys(m.GetShortcuts()) {
155			seen[k]++
156		}
157		for k, n := range seen {
158			if n > 1 {
159				t.Errorf("key %q announced %d times on the results", k, n)
160			}
161		}
162		if seen[keymap.Diagnose] != 1 {
163			t.Errorf("H announced %d times, want once", seen[keymap.Diagnose])
164		}
165	}
166	
167	func TestHWhileAPathTraceRunsSwitchesTabAndLeavesTheTraceAlone(t *testing.T) {
168		m, _ := routeResults(t, "example.com")
169		m = selectCheck(t, m, netcheck.CheckRoute)
170		m.activeTab = tabPath
171		m = feed(t, m, testutil.Type("1.1.1.1")...)
172		m = feed(t, m, testutil.Key("enter"))
173		if !m.pathModel.running() {
174			t.Fatal("setup: no path trace running")
175		}
176		m.activeTab = tabDiagnostics
177	
178		m = feed(t, m, testutil.Key(keymap.Diagnose))
179	
180		if m.activeTab != tabPath {
181			t.Errorf("activeTab = %d, want tabPath", m.activeTab)
182		}
183		if !m.pathModel.running() || m.pathModel.input.Value() != "1.1.1.1" {
184			t.Errorf("running=%v field=%q, want the trace and its field untouched", m.pathModel.running(), m.pathModel.input.Value())
185		}
186		const want = "A path trace is already running — esc cancels it"
187		if m.pathModel.footer.Level() != components.LevelWarning || m.pathModel.footer.Text() != want {
188			t.Errorf("Path footer = {%v %q}, want Warn %q", m.pathModel.footer.Level(), m.pathModel.footer.Text(), want)
189		}
190	}
191	
192	func TestHIsInertInTheFormAndWhileRunning(t *testing.T) {
193		m := typeInto(t, newTestModel(t), "")
194		m = feed(t, m, testutil.Key(keymap.Diagnose))
195		if m.activeTab != tabDiagnostics || m.targetInput.Value() != "H" {
196			t.Errorf("form: tab=%d field=%q, want H typed into the field and no switch", m.activeTab, m.targetInput.Value())
197		}
198	
199		r := runningModel(t, "example.com")
200		r = feed(t, r, testutil.Key(keymap.Diagnose))
201		if r.activeTab != tabDiagnostics || r.state != StateRunning || r.pathModel.input.Value() != "" {
202			t.Errorf("running: tab=%d state=%v path=%q, want H inert", r.activeTab, r.state, r.pathModel.input.Value())
203		}
204	}
205	
206	func TestHOnDetailsIsInert(t *testing.T) {
207		m, _ := routeResults(t, "example.com")
208		m = selectCheck(t, m, netcheck.CheckRoute)
209		m = feed(t, m, testutil.Key("enter"))
210		m = feed(t, m, testutil.Key(keymap.Diagnose))
211		if m.activeTab != tabDiagnostics || m.state != StateDetails {
212			t.Errorf("details: tab=%d state=%v, want H inert", m.activeTab, m.state)
213		}
214	}
215	
216	func TestHelpMentionsHOnTheResults(t *testing.T) {
217		var found bool
218		for _, kb := range New(testConfig()).GetHelpContent().KeyBindings {
219			if strings.HasPrefix(kb.Key, keymap.Diagnose) && strings.Contains(kb.Key, "results") {
220				found = strings.Contains(strings.ToLower(kb.Description), "path") &&
221					strings.Contains(kb.Description, "Local route")
222			}
223		}
224		if !found {
225			t.Error(`help lacks a binding "H (results)" whose description names the Path trace and the Local route row`)
226		}
